module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel0, not_sel1;
    wire and0_out, and1_out, and2_out, and3_out;

    not not0(not_sel0, sel[0]);
    not not1(not_sel1, sel[1]);

    and and0(and0_out, in[0], not_sel1, not_sel0);
    and and1(and1_out, in[1], not_sel1, sel[0]);
    and and2(and2_out, in[2], sel[1], not_sel0);
    and and3(and3_out, in[3], sel[1], sel[0]);

    or or0(out, and0_out, and1_out, and2_out, and3_out);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_sel0, not_sel1;
    wire and0, and1, and2, and3;

    // NOT gates for select signals
    not(not_sel0, sel[0]);
    not(not_sel1, sel[1]);

    // AND gates for each input with corresponding select conditions
    and(and0, in[0], not_sel1, not_sel0);  // sel=00
    and(and1, in[1], not_sel1, sel[0]);    // sel=01
    and(and2, in[2], sel[1], not_sel0);    // sel=10
    and(and3, in[3], sel[1], sel[0]);      // sel=11

    // OR gate to combine all AND outputs
    or(out, and0, and1, and2, and3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_sel0, not_sel1;
    wire and0_out, and1_out, and2_out, and3_out;

    // Invert select signals
    not not0(not_sel0, sel[0]);
    not not1(not_sel1, sel[1]);

    // AND gates for each input with corresponding select conditions
    and and0(and0_out, in[0], not_sel1, not_sel0);  // sel = 00
    and and1(and1_out, in[1], not_sel1, sel[0]);     // sel = 01
    and and2(and2_out, in[2], sel[1], not_sel0);     // sel = 10
    and and3(and3_out, in[3], sel[1], sel[0]);       // sel = 11

    // OR gate to combine all AND outputs
    or or_out(out, and0_out, and1_out, and2_out, and3_out);

endmodule

