module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] state_reg;
    reg [1:0] next_state;

    // State encoding
    parameter A = 2'b00;
    parameter B = 2'b01;
    parameter C = 2'b10;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= A;
        end else begin
            state_reg <= next_state;
        end
    end

    // Next state logic
    always @(state_reg) begin
        case (state_reg)
            A: next_state = B;
            B: next_state = C;
            C: next_state = A;
            default: next_state = A;
        endcase
    end

    // Output assignment
    assign state = state_reg;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    // State definitions
    parameter [1:0] A = 2'b00,
                    B = 2'b01,
                    C = 2'b10;

    // State register
    reg [1:0] state_reg;

    // Sequential logic for state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= A;
        end else begin
            case (state_reg)
                A: state_reg <= B;
                B: state_reg <= C;
                C: state_reg <= A;
                default: state_reg <= A;
            endcase
        end
    end

    // Output assignment
    assign state = state_reg;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    // State definitions
    localparam [1:0] A = 2'b00;
    localparam [1:0] B = 2'b01;
    localparam [1:0] C = 2'b10;

    // State register
    reg [1:0] state_reg;

    // Sequential logic for state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= A;
        end else begin
            case (state_reg)
                A: state_reg <= B;
