module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    reg signed [7:0] result;
    reg signed [15:0] x;
    reg signed [15:0] low, high, mid;
    reg [3:0] count;
    reg computing;

    assign out = result;

    always @(*) begin
        if (in_0 < 0) begin
            x = 0;
        end else begin
            x = in_0;
        end
    end

    always @(x) begin
        if (x == 0) begin
            result = 0;
            computing = 0;
        end else begin
            low = 1;
            high = (x > 32767) ? 32767 : x;
            computing = 1;
            count = 0;
        end
    end

    always @(posedge computing) begin
        if (computing && count < 8) begin
            mid = (low + high) >> 1;
            if (mid * mid <= x) begin
                low = mid;
                if ((mid + 1) * (mid + 1) > x) begin
                    result = mid[7:0];
                    computing = 0;
                end
            end else begin
                high = mid;
            end
            count = count + 1;
            if (count == 8) begin
