module modulo_op (
    input [7:0] a,
    input [7:0] b,
    output [7:0] remainder
);

    reg [7:0] temp_a;
    reg [7:0] temp_remainder;

    always @(*) begin
        temp_a = a;
        if (b == 8'b0) begin
            temp_remainder = 8'b0;
        end else begin
            while (temp_a >= b) begin
                temp_a = temp_a - b;
            end
            temp_remainder = temp_a;
        end
    end

    assign remainder = temp_remainder;

endmodule

