    reg [7:0] a_stage1, b_stage1;
    reg [7:0] partial_products [0:7];
    integer i;

    // Stage 2: Intermediate accumulation registers
    reg [15:0] sum_stage2;
    reg [15:0] stage2_reg;

    // Stage 3: Final result register
    reg [15:0] stage3_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all pipeline registers
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 8'b0;
            end
            sum_stage2 <= 16'b0;
            stage2_reg <= 16'b0;
            stage3_reg <= 16'b0;
            out <= 16'b0;
        end else begin
            // Stage 1: Calculate partial products
            a_stage1 <= a;
            b_stage1 <= b;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= b[i] ? a : 8'b0;
            end

            // Stage 2: Accumulate partial products with shifting
            sum_stage2 <= 16'b0;
            for (i = 0; i < 8; i = i + 1) begin
                sum_stage2 <= sum_stage2 + (partial_products[i] << i);
            end
            stage2_reg <= sum_stage2;

            // Stage 3: Final result
            stage3_reg <= stage2_reg;
            out <= stage3_reg;
        end
