module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

// Coefficients (example values - can be changed as needed)
parameter [7:0] c0 = 8'h10;
parameter [7:0] c1 = 8'h20;
parameter [7:0] c2 = 8'h30;
parameter [7:0] c3 = 8'h40;

// Input shift register (4-tap delay line)
reg [7:0] x_delay [0:3];
integer i;

// Stage 1: Multiplication results
reg [15:0] prod0, prod1, prod2, prod3;

// Stage 2: Partial sums
reg [15:0] sum01, sum23;

// Stage 3: Final sum
reg [15:0] final_sum;

// Input shift register and pipeline stages
always @(posedge clk or posedge rst) begin
    if (rst) begin
        // Reset all registers
        for (i = 0; i < 4; i = i + 1) begin
            x_delay[i] <= 8'b0;
        end
        prod0 <= 16'b0;
        prod1 <= 16'b0;
        prod2 <= 16'b0;
        prod3 <= 16'b0;
        sum01 <= 16'b0;
        sum23 <= 16'b0;
        final_sum <= 16'b0;
        y <= 16'b0;
    end else begin
        // Stage 1: Update input shift register and perform multiplications
        x_delay[0] <= x;
        for (i = 1; i < 4; i = i + 1) begin
            x_delay[i] <= x_delay[i-1];
        end

        prod0 <= x_delay[0] * c0;
        prod1 <= x_delay[1] * c1;
        prod2 <= x_delay[2] * c2;
        prod3 <= x_delay[3] * c3;

        // Stage 2: Add partial products
        sum01 <= prod0 + prod1;
        sum23 <= prod2 + prod3;

        // Stage 3: Final accumulation
        final_sum <= sum01 + sum23;

        // Output
        y <= final_sum;
    end
end

endmodule

