    parameter [7:0] h2 = 8'h03;
    parameter [7:0] h3 = 8'h04;

    // Input shift register (4 samples)
    reg [7:0] x_reg [0:3];

    // Stage 1: Multiplications
    reg [15:0] prod0, prod1, prod2, prod3;

    // Stage 2: Partial sums
    reg [15:0] sum01, sum23;

    // Stage 3: Final sum
    reg [15:0] sum_final;

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all registers
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 8'b0;
            end
            prod0 <= 16'b0;
            prod1 <= 16'b0;
            prod2 <= 16'b0;
            prod3 <= 16'b0;
            sum01 <= 16'b0;
            sum23 <= 16'b0;
            sum_final <= 16'b0;
            y <= 16'b0;
        end else begin
            // Stage 1: Shift input and compute products
            x_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            prod0 <= x_reg[0] * h0;
            prod1 <= x_reg[1] * h1;
            prod2 <= x_reg[2] * h2;
            prod3 <= x_reg[3] * h3;

            // Stage 2: Partial additions
            sum01 <= prod0 + prod1;
            sum23 <= prod2 + prod3;

            // Stage 3: Final addition and output
            sum_final <= sum01 + sum23;
            y <= sum_final;
        end
    end

endmodule

