module mse_loss (
    input signed [15:0] in_0_0, input signed [15:0] in_0_1, input signed [15:0] in_0_2, input signed [15:0] in_0_3, // Ground truth vector
    input signed [15:0] in_1_0, input signed [15:0] in_1_1, input signed [15:0] in_1_2, input signed [15:0] in_1_3, // Predicted vector
    output signed [31:0] out);

    // Step 1: Compute differences
    wire signed [16:0] diff_0, diff_1, diff_2, diff_3;
    assign diff_0 = in_0_0 - in_1_0;
    assign diff_1 = in_0_1 - in_1_1;
    assign diff_2 = in_0_2 - in_1_2;
    assign diff_3 = in_0_3 - in_1_3;

    // Step 2: Square the differences
    wire signed [33:0] sq_0, sq_1, sq_2, sq_3;
    assign sq_0 = diff_0 * diff_0;
    assign sq_1 = diff_1 * diff_1;
    assign sq_2 = diff_2 * diff_2;
    assign sq_3 = diff_3 * diff_3;

    // Step 3: Sum all squared errors
    wire signed [35:0] sum_sq;
    assign sum_sq = sq_0 + sq_1 + sq_2 + sq_3;

    // Step 4: Divide by 4 (right shift by 2) to get MSE
    assign out = sum_sq[35:2];

endmodule

