    output signed [31:0] out_0, output signed [31:0] out_1, output signed [31:0] out_2, output signed [31:0] out_3);

    wire signed [15:0] input_matrix [0:2][0:2];
    wire signed [15:0] kernel [0:1][0:1];

    assign input_matrix[0][0] = in_0_0;
    assign input_matrix[0][1] = in_0_1;
