module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output [31:0] A
);

    reg [31:0] result;
    reg [31:0] intermediate;
    reg [7:0] counter;

    always @(*) begin
        if (n == 0) begin
            result = 32'd1;
        end else begin
            intermediate = {16'd0, 8'd1, r}; // 1 + r in fixed-point (24.8 format)
            result = intermediate;
            counter = n - 1;

            while (counter > 0) begin
                result = result * intermediate;
                counter = counter - 1;
                if (counter == 0) begin
                    disable loop;
                end
            end
            loop: ;
        end

        // Multiply by P and adjust for fixed-point scaling
        A = (P * result[31:8]); // Shift right by 8 bits to correct fixed-point
    end

endmodule

module compound_interest (
