    always @(*) begin
        if (n == 0) begin
            acc = 32'd256; // (1+r)^0 = 1, scaled by 256
        end else begin
            acc = {16'd0, 8'd1, r}; // 1 + r in 8.8 format: actually 256 + r
            for (i = 1; i < n; i = i + 1) begin
                temp = acc * (16'd256 + r);
                acc = temp >> 8; // divide by 256 to maintain scale
            end
        end
        // Final multiply by P and scale down
        A = (P * acc) >> 8;
    end

endmodule

