        end else begin
            intermediate = 32'd1 + {16'd0, r};
            result = 32'd1;
            for (counter = 0; counter < n; counter = counter + 1) begin
                result = result * intermediate;
            end
        end
    end

    assign A = result * {16'd0, P};

endmodule

module compound_interest (
