    output reg [15:0] quotient,
    output reg [15:0] remainder
);

    integer i;
    reg [31:0] temp_dividend;
    reg [15:0] temp_divisor;

    always @(*) begin
        temp_dividend = {16'b0, dividend};
        temp_divisor = divisor;
        quotient = 16'b0;

        for (i = 15; i >= 0; i = i - 1) begin
            temp_dividend = temp_dividend << 1;
            if (temp_dividend[31:16] >= temp_divisor) begin
                temp_dividend[31:16] = temp_dividend[31:16] - temp_divisor;
                quotient[i] = 1'b1;
