module present_value (
    input [15:0] future_amount,
    input [7:0] rate,
    input [7:0] n,
    output reg [15:0] present_value
);

    // Internal registers
    reg [31:0] base_scaled;   // (1 + rate/100) scaled by 2^16
    reg [31:0] power_result;  // (1 + rate/100)^n scaled by 2^16
    reg [31:0] denominator;   // power_result after n multiplications
    reg [31:0] dividend;      // future_amount scaled for division
    reg [31:0] divisor;       // denominator for division
    reg [31:0] quotient;      // division result
    reg [31:0] remainder;     // remainder for division
    integer i, j;

    always @(*) begin
        // Step 1: Compute base_scaled = (1 + rate/100) in fixed-point (scaled by 2^16)
        // rate/100 = rate * (2^16) / 100
        base_scaled = (32'd1 << 16) + ((rate * (32'd1 << 16)) / 100);

        // Step 2: Compute power_result = base_scaled^n
        power_result = (32'd1 << 16); // Start with 1.0 in fixed-point
        for (i = 0; i < n; i = i + 1) begin
            power_result = (power_result * base_scaled) >> 16;
        end

        // Step 3: Perform division: future_amount / (power_result >> 16)
        // But power_result is scaled by 2^16, so:
        // present_value = (future_amount << 16) / power_result
        dividend = future_amount << 16;
        divisor = power_result;
        quotient = 0;
        remainder = 0;

        // Restoring division algorithm
        for (j = 31; j >= 0; j = j - 1) begin
            remainder = remainder << 1;
            remainder[0] = dividend[j];
            if (remainder >= divisor) begin
                remainder = remainder - divisor;
                quotient[j] = 1'b1;
            end
        end

        // quotient now holds (future_amount << 16) / power_result
        // But we only need the lower 16 bits as integer result
        present_value = quotient[15:0];
    end

endmodule

module present_value (
