        // Step 1: Calculate base = 1 + rate/100 with scaling (scale by 2^16)
        base_scaled = 32'd65536 + ((rate * 32'd65536) / 100);

        // Step 2: Compute power_result = base_scaled^n
        if (n == 0) begin
            power_result = 32'd65536; // 1.0 in fixed-point
        end else begin
            power_result = base_scaled;
            for (i = 1; i < n; i = i + 1) begin
                power_result = (power_result * base_scaled) >> 16;
            end
        end

        // Step 3: Perform division: present_value = future_amount / (power_result / 65536)
        // This is equivalent to: present_value = (future_amount * 65536) / power_result
        dividend = future_amount * 32'd65536;
        divisor = power_result;
        quotient = 0;
        remainder = dividend;

        for (j = 31; j >= 0; j = j - 1) begin
            remainder = remainder << 1;
            if (remainder >= divisor) begin
                remainder = remainder - divisor;
                quotient = quotient | (1 << j);
            end
        end

        // Step 4: Scale down and assign output
        if (quotient[31:16] > 16'hFFFF) begin
            present_value = 16'hFFFF; // Saturate at maximum
        end else begin
            present_value = quotient[31:16];
        end
    end

