    input [7:0] n,
    output reg [15:0] present_value
);

    reg [31:0] rate_fraction;
    reg [31:0] base;
    reg [31:0] power_result;
    integer i, j;
    reg [31:0] numerator;
    reg [31:0] denominator;
    reg [31:0] quotient;
    reg [31:0] remainder;

    always @(*) begin
        // Step 1: Compute rate_fraction = (rate * 2^16) / 100
        rate_fraction = 0;
        for (i = 0; i < rate; i = i + 1) begin
            rate_fraction = rate_fraction + (65536 / 100);
        end

        // Step 2: base = 1 + rate_fraction in fixed-point (scaled by 2^16)
        base = 65536 + rate_fraction;

        // Step 3: Compute base^n (scaled by 2^16 each time)
        power_result = 65536; // when n=0, result is 1 in fixed-point
        if (n != 0) begin
            power_result = base;
            for (i = 1; i < n; i = i + 1) begin
                // Multiply two 32-bit fixed-point numbers (16 fractional bits)
                // Result should be scaled by 2^16 again, so we divide by 2^16 after multiplication
                // But to avoid losing precision, we keep intermediate as 48 bits then shift
                power_result = (power_result * base) >> 16;
            end
        end

        // Step 4: Divide future_amount by power_result in fixed-point
        // We compute: (future_amount << 16) / power_result
        numerator = future_amount << 16;
        denominator = power_result;
        quotient = 0;
        remainder = numerator;

        if (denominator != 0) begin
            for (j = 31; j >= 0; j = j - 1) begin
                if (remainder >= (denominator << j)) begin
                    quotient = quotient + (1 << j);
                    remainder = remainder - (denominator << j);
                end
            end
        end else begin
            quotient = 0; // division by zero
        end

        // quotient now contains the fixed-point result, scale back to integer
        present_value = quotient[15:0];
    end

endmodule

module present_value (
