    reg [31:0] numerator;
    reg [31:0] denominator;
    reg [7:0] counter;
    reg [31:0] temp;
    reg [31:0] quotient;
    reg [31:0] remainder;
    integer i;

    always @(*) begin
        // Step 1: Calculate base = 1 + rate/100 with scaling (scale by 2^16)
        base_scaled = (32'd65536) + ((rate * 32'd655) / 32'd100);

        // Step 2: Compute power_result = base_scaled^n
        if (n == 0) begin
            power_result = 32'd65536;  // (1 + 0)^0 = 1, scaled by 2^16
        end else begin
            power_result = base_scaled;
            counter = n - 1;
            temp = base_scaled;

            for (i = 0; i < 255; i = i + 1) begin
                if (i < counter) begin
                    temp = (temp * base_scaled) >> 16;
                end else begin
                    i = 255;  // exit loop
                end
            end

            if (n > 1) begin
                power_result = temp;
            end
        end

        // Step 3: Perform division: present_value = future_amount / (power_result/65536)
        // Equivalent to: present_value = (future_amount * 65536) / power_result
        numerator = future_amount * 32'd65536;
        denominator = power_result;

        // Simple division algorithm
        quotient = 0;
        remainder = 0;

        for (i = 31; i >= 0; i = i - 1) begin
            remainder = remainder << 1;
            remainder[0] = numerator[i];

            if (remainder >= denominator) begin
                remainder = remainder - denominator;
                quotient[i] = 1;
            end
        end

        // Final result (scaled back down)
        present_value = quotient[15:0];
    end

endmodule

module present_value (
    input [15:0] future_amount,
    input [7:0] rate,
    input [7:0] n,
    output reg [15:0] present_value
);

    reg [31:0] base_scaled;
    reg [31:0] denominator;
    reg [31:0] temp;
    reg [7:0] counter;
    reg [31:0] dividend;
    reg [31:0] quotient;
    reg [31:0] divisor;
    reg [4:0] div_counter;

    always @(*) begin
        // Step 1: Calculate base = 1 + rate/100 with scaling (scale by 2^16)
        base_scaled = 32'd65536 + (rate * 32'd655); // 65536/100 ≈ 655

        // Step 2: Compute denominator = base_scaled^n
        if (n == 0) begin
            denominator = 32'd65536; // (1 + rate/100)^0 = 1
        end else begin
            denominator = base_scaled;
            counter = n - 1;
            temp = base_scaled;
            while (counter > 0) begin
                denominator = denominator * temp;
                denominator = denominator >> 16; // Maintain fixed-point scaling
                counter = counter - 1;
            end
        end

        // Step 3: Perform division: present_value = future_amount * 2^16 / denominator
        dividend = future_amount << 16;
        divisor = denominator;
        quotient = 0;

        for (div_counter = 0; div_counter < 32; div_counter = div_counter + 1) begin
            quotient = quotient << 1;
            if (dividend >= divisor) begin
                dividend = dividend - divisor;
                quotient = quotient | 1;
            end
            dividend = dividend << 1;
        end

        // Step 4: Final scaling and output
        present_value = quotient[15:0];
    end

endmodule

module currency_converter (
