    wire [31:0] truncated_result;
    wire round_bit;

    // Multiply 32-bit amount by 16-bit conversion rate
    assign full_product = amount * conversion_rate;

    // Extract the integer part (bits 47:16) and round based on fractional part
    assign truncated_result = full_product[47:16];
