module kinetic_energy (
    input [7:0] mass,      // mass in kilograms
    input [7:0] velocity,  // velocity in m/s
    output [15:0] energy
);

    wire [15:0] v_squared;
    wire [23:0] intermediate_product;
    wire [23:0] half_product;

    // Square the velocity (v^2)
    assign v_squared = velocity * velocity;

    // Multiply by mass (m * v^2)
    assign intermediate_product = mass * v_squared;

    // Divide by 2 using right shift (1/2 * m * v^2)
    assign half_product = intermediate_product >> 1;

    // Take lower 16 bits as final energy output
    assign energy = half_product[15:0];

endmodule

