module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    wire signed [15:0] T_signed = {8'b0, temperature};
    wire signed [15:0] R_signed = {8'b0, humidity};

    wire signed [31:0] T_sq = T_signed * T_signed;
    wire signed [31:0] R_sq = R_signed * R_signed;

    wire signed [31:0] term1 = C1;
    wire signed [31:0] term2 = C2 * T_signed;
    wire signed [31:0] term3 = C3 * R_signed;
    wire signed [31:0] term4 = C4 * T_signed * R_signed;
    wire signed [31:0] term5 = C5 * T_sq;
    wire signed [31:0] term6 = C6 * R_sq;
    wire signed [31:0] term7 = C7 * T_sq * R_signed;
    wire signed [31:0] term8 = C8 * T_signed * R_sq;
    wire signed [31:0] term9 = C9 * T_sq * R_sq;

    wire signed [31:0] sum = term1 + term2 + term3 + term4 + term5 + 
                           term6 + term7 + term8 + term9;

    assign heat_index = sum[31:16] + (sum[15] ? 16'sd1 : 16'sd0);

endmodule

