module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    // Convert inputs to signed for arithmetic operations
    wire signed [8:0] T_signed = {1'b0, temperature};
    wire signed [8:0] R_signed = {1'b0, humidity};

    // Intermediate terms
    wire signed [24:0] term1;  // C1
    wire signed [24:0] term2;  // C2*T
    wire signed [24:0] term3;  // C3*R
    wire signed [24:0] term4;  // C4*T*R
    wire signed [24:0] term5;  // C5*T^2
    wire signed [24:0] term6;  // C6*R^2
    wire signed [24:0] term7;  // C7*T^2*R
    wire signed [24:0] term8;  // C8*T*R^2
    wire signed [24:0] term9;  // C9*T^2*R^2

    wire signed [16:0] T_sq;   // T^2
    wire signed [16:0] R_sq;   // R^2
    wire signed [17:0] T_R;    // T*R
    wire signed [25:0] T_sq_R; // T^2*R
    wire signed [25:0] T_R_sq; // T*R^2
    wire signed [33:0] T_sq_R_sq; // T^2*R^2

    // Calculate basic squares and products
    assign T_sq = T_signed * T_signed;
    assign R_sq = R_signed * R_signed;
    assign T_R = T_signed * R_signed;

    // Calculate higher-order terms
    assign T_sq_R = T_sq * R_signed;
    assign T_R_sq = T_signed * R_sq;
    assign T_sq_R_sq = T_sq * R_sq;

    // Calculate each polynomial term
    assign term1 = C1;
    assign term2 = C2 * T_signed;
    assign term3 = C3 * R_signed;
    assign term4 = C4 * T_R;
    assign term5 = C5 * T_sq;
    assign term6 = C6 * R_sq;
    assign term7 = C7 * T_sq_R;
    assign term8 = C8 * T_R_sq;
    assign term9 = C9 * T_sq_R_sq;

    // Sum all terms with proper bit-width management
    wire signed [33:0] sum_temp;

    assign sum_temp = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Final output - truncate to 16 bits with saturation logic
    assign heat_index = (sum_temp > 32767) ? 16'sd32767 :
                      (sum_temp < -32768) ? 16'sd-32768 :
                      sum_temp[15:0];

endmodule

module air_quality_index (
    input [7:0] pm2_5,
    input [7:0] pm10,
    input [7:0] no2,
    output [15:0] aqi
);

    wire [7:0] max_val;
    wire [7:0] min_val;
    wire [9:0] sum_val;

    // Find maximum value
    assign max_val = (pm2_5 >= pm10 && pm2_5 >= no2) ? pm2_5 :
                    (pm10 >= pm2_5 && pm10 >= no2) ? pm10 : no2;

    // Find minimum value
    assign min_val = (pm2_5 <= pm10 && pm2_5 <= no2) ? pm2_5 :
                    (pm10 <= pm2_5 && pm10 <= no2) ? pm10 : no2;

    // Calculate sum
    assign sum_val = pm2_5 + pm10 + no2;

    // Weighted calculations with fixed-point scaling (multiply by 256 for 8-bit fractional precision)
    wire [15:0] weighted_max = max_val * 128;  // 0.5 * 256 = 128
    wire [15:0] weighted_min = min_val * 77;   // 0.3 * 256 ≈ 76.8 → 77
    wire [15:0] weighted_sum = sum_val * 51;   // 0.2 * 256 = 51.2 → 51

    // Final AQI calculation (divide by 256 to scale back)
    assign aqi = (weighted_max + weighted_min + weighted_sum) >> 8;

endmodule

