module air_quality_index (
    input [7:0] pm2_5,
    input [7:0] pm10,
    input [7:0] no2,
    output [15:0] aqi
);

    wire [7:0] max_val;
    wire [7:0] min_val;
    wire [9:0] sum_val;

    // Find maximum value
    assign max_val = (pm2_5 >= pm10 && pm2_5 >= no2) ? pm2_5 :
                    (pm10 >= pm2_5 && pm10 >= no2) ? pm10 : no2;

    // Find minimum value
    assign min_val = (pm2_5 <= pm10 && pm2_5 <= no2) ? pm2_5 :
                    (pm10 <= pm2_5 && pm10 <= no2) ? pm10 : no2;

    // Calculate sum
    assign sum_val = pm2_5 + pm10 + no2;

    // Weighted calculations (using fixed-point arithmetic)
    // Multiply by 0.5 = divide by 2 (right shift 1)
    wire [15:0] weighted_max = {8'b0, max_val} * 8'd128; // 0.5 * 256 = 128

    // Multiply by 0.3 = approximately 77/256
    wire [15:0] weighted_min = {8'b0, min_val} * 8'd77;  // 0.3 * 256 ≈ 77

    // Multiply by 0.2 = approximately 51/256
    wire [15:0] weighted_sum = {6'b0, sum_val} * 8'd51;  // 0.2 * 256 ≈ 51

    // Sum all weighted values and divide by 256 to scale back
    assign aqi = (weighted_max + weighted_min + weighted_sum) >> 8;

endmodule

module air_quality_index (
