                    (pm10 <= pm2_5 && pm10 <= no2) ? pm10 : no2;

    // Sum calculation
    assign sum_val = pm2_5 + pm10 + no2;

    // Weighted calculations (using fixed-point arithmetic with scaling)
    // Multiply by 0.5 = right shift by 1
    wire [7:0] weighted_max = max_val >> 1;

    // Multiply by 0.3 = approximately multiply by 77 then divide by 256 (77/256 ≈ 0.3008)
    wire [15:0] min_times_77 = min_val * 8'd77;
    wire [7:0] weighted_min = min_times_77[15:8];

    // Multiply by 0.2 = multiply by 51 then divide by 256 (51/256 ≈ 0.1992)
    wire [15:0] sum_times_51 = sum_val * 8'd51;
    wire [7:0] weighted_sum = sum_times_51[15:8];

    // Final AQI calculation
    assign aqi = weighted_max + weighted_min + weighted_sum;

endmodule

